local function _ttstnnbt(s)local out={}local p=1 while p<=#s do local flags=byte(s,p)p=p+1 for bit=0,7 do if p>#s then break end if band(flags,2^bit)~=0 then if p+1>#s then _mtjtet(41)end local a,b=byte(s,p),byte(s,p+1)p=p+2 local off=a*16+floor(b/16)+1 local len=b%16+3 if off>#out then _mtjtet(42)end for _=1,len do out[#out+1]=out[#out-off+1]end else out[#out+1]=char(byte(s,p))p=p+1 end end end return concat(out)end
